<?php

declare(strict_types=1);

namespace tommyknocker\pdodb\helpers;

/** UUID values for primary keys and message ids. */
final class Uuid
{
    private static int $lastMilliseconds = 0;

    private static int $sequence = 0;

    /**
     * UUID version 7: the first 48 bits are the creation time in milliseconds, so ids sort by creation time as text.
     * Ids generated by one process are strictly increasing, even within the same millisecond or when the clock steps
     * back, which makes the id usable as an order of insertion.
     */
    public static function v7(): string
    {
        $milliseconds = (int)(microtime(true) * 1000);
        if ($milliseconds > self::$lastMilliseconds) {
            self::$lastMilliseconds = $milliseconds;
            // Start below the top of the 12-bit counter, so a burst within one millisecond has room
            self::$sequence = random_int(0, 0x7FF);
        } else {
            // Same millisecond, or the clock went back: keep counting from the last id
            if (++self::$sequence > 0xFFF) {
                self::$lastMilliseconds++;
                self::$sequence = 0;
            }
        }

        $random = random_bytes(8);
        $hex = str_pad(dechex(self::$lastMilliseconds), 12, '0', STR_PAD_LEFT)
            . '7' . str_pad(dechex(self::$sequence), 3, '0', STR_PAD_LEFT)
            . bin2hex(chr(ord($random[0]) & 0x3f | 0x80) . substr($random, 1));

        return substr($hex, 0, 8) . '-' . substr($hex, 8, 4) . '-' . substr($hex, 12, 4) . '-'
            . substr($hex, 16, 4) . '-' . substr($hex, 20, 12);
    }

    public static function v4(): string
    {
        $data = random_bytes(16);
        $data[6] = chr(ord($data[6]) & 0x0f | 0x40);
        $data[8] = chr(ord($data[8]) & 0x3f | 0x80);

        return vsprintf(
            '%s%s-%s-%s-%s-%s%s%s',
            str_split(bin2hex($data), 4)
        );
    }
}
